import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import AddProductPage from './AddProductPage'; // Import your separate add product file
import './CSS/SellerDashboard.css';

function SellerDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview'); // 'overview', 'products', 'addProduct'
  const [sellerProducts, setSellerProducts] = useState([]);

  useEffect(() => {
    fetchSellerProducts();
  }, []);

  const fetchSellerProducts = async () => {
    try {
      const response = await axios.get('http://localhost:4000/api/seller/products');
      if (Array.isArray(response.data)) {
        setSellerProducts(response.data);
      } else if (response.data && Array.isArray(response.data.products)) {
        setSellerProducts(response.data.products);
      }
    } catch (err) {
      console.error('Error fetching seller products:', err);
    }
  };

  return (
    <div className="seller-dashboard-container" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc' }}>
      
      {/* Sidebar Navigation */}
      <div className="seller-sidebar" style={{ width: '260px', backgroundColor: '#fff', borderRight: '1px solid #e2e8f0', padding: '24px' }}>
        <h2 style={{ fontSize: '20px', fontWeight: '800', color: '#130352', marginBottom: '30px' }}>Seller Panel</h2>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <button 
            onClick={() => setActiveTab('overview')} 
            style={{
              padding: '12px 16px',
              textAlign: 'left',
              backgroundColor: activeTab === 'overview' ? '#130352' : 'transparent',
              color: activeTab === 'overview' ? '#fff' : '#475569',
              border: 'none',
              borderRadius: '8px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            Dashboard Overview
          </button>

          <button 
            onClick={() => setActiveTab('products')} 
            style={{
              padding: '12px 16px',
              textAlign: 'left',
              backgroundColor: activeTab === 'products' ? '#130352' : 'transparent',
              color: activeTab === 'products' ? '#fff' : '#475569',
              border: 'none',
              borderRadius: '8px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            My Products ({sellerProducts.length})
          </button>

          <button 
            onClick={() => setActiveTab('addProduct')} 
            style={{
              padding: '12px 16px',
              textAlign: 'left',
              backgroundColor: activeTab === 'addProduct' ? '#130352' : 'transparent',
              color: activeTab === 'addProduct' ? '#fff' : '#475569',
              border: 'none',
              borderRadius: '8px',
              fontWeight: 'bold',
              cursor: 'pointer'
            }}
          >
            + Add New Product
          </button>
        </div>

        <div style={{ marginTop: '50px', borderTop: '1px solid #e2e8f0', paddingTop: '20px' }}>
          <button 
            onClick={() => navigate('/')} 
            style={{ width: '100%', padding: '10px', backgroundColor: '#f1f5f9', border: 'none', borderRadius: '8px', fontWeight: 'bold', color: '#475569', cursor: 'pointer' }}
          >
            Back to Store Home
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="seller-main-content" style={{ flex: 1, padding: '30px', overflowY: 'auto' }}>
        
        {activeTab === 'overview' && (
          <div>
            <h2 style={{ fontSize: '24px', fontWeight: '800', color: '#0f172a', marginBottom: '20px' }}>Dashboard Overview</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' }}>
              <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
                <h4 style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '14px' }}>Total Products Listed</h4>
                <span style={{ fontSize: '28px', fontWeight: '800', color: '#130352' }}>{sellerProducts.length}</span>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'products' && (
          <div>
            <h2 style={{ fontSize: '24px', fontWeight: '800', color: '#0f172a', marginBottom: '20px' }}>My Products</h2>
            {sellerProducts.length === 0 ? (
              <p style={{ color: '#64748b' }}>No products found. Click "+ Add New Product" to list one.</p>
            ) : (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '20px' }}>
                {sellerProducts.map(prod => (
                  <div key={prod._id} style={{ backgroundColor: '#fff', padding: '15px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
                    <img 
                      src={prod.images?.[0] ? `http://localhost:4000${prod.images[0]}` : 'https://via.placeholder.com/150'} 
                      alt={prod.title} 
                      style={{ width: '100%', height: '140px', objectFit: 'contain', marginBottom: '10px', backgroundColor: '#f8fafc', borderRadius: '8px' }} 
                    />
                    <h4 style={{ fontSize: '14px', fontWeight: '700', margin: '0 0 6px 0', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{prod.title}</h4>
                    <span style={{ fontSize: '16px', fontWeight: '800', color: '#130352' }}>${prod.price}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Renders your separate AddProductPage component cleanly */}
        {activeTab === 'addProduct' && (
          <AddProductPage />
        )}

      </div>
    </div>
  );
}

export default SellerDashboard;
